children.nodeValue:
html {
  background: white;
  /* Remove 300ms delay for 'click' event, when using touch interface. */
  touch-action: manipulation;
}

@media (prefers-color-scheme: dark) {
  html {
    background: rgb(40, 41, 44);
  }
}

html,
body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  width: 100%;
}

.loading body {
}

.loading body::before {
  background: rgb(218, 220, 224);  /* --google-grey-300 */
  border-bottom-width: 0;
  border-color: rgb(232, 234, 237);
  border-inline-end-width: 1px;
  border-inline-start-width: 0;
  border-style: solid;
  border-top-width: 0;
  content: '';
  display: block;
  height: 100%;
  width: calc(100% - 385px);  /* --print-preview-sidebar-width */
}

@media (prefers-color-scheme: dark) {
  .loading body::before {
    background: rgb(95, 99, 104);  /* --google-grey-700 */
    border-color: rgba(40, 41, 44, .9);
  }
}
